private class P(
    val d: String,
    val stroke: Boolean,
    val alpha: Float,
    val width: Float,
    val roundCap: Boolean,
    val roundJoin: Boolean,
    val evenOdd: Boolean
)

private fun icon(name: String, vararg parts: P): ImageVector {
    val b = ImageVector.Builder(
        name           = name,
        defaultWidth   = 24.dp,
        defaultHeight  = 24.dp,
        viewportWidth  = 24f,
        viewportHeight = 24f
    )
    for (p in parts) {
        val nodes = PathParser().parsePathString(p.d).toNodes()
        if (p.stroke) {
            b.addPath(
                pathData        = nodes,
                fill            = null,
                stroke          = SolidColor(Color.Black),
                strokeAlpha     = p.alpha,
                strokeLineWidth = p.width,
                strokeLineCap   = if (p.roundCap) StrokeCap.Round else StrokeCap.Butt,
                strokeLineJoin  = if (p.roundJoin) StrokeJoin.Round else StrokeJoin.Miter
            )
        } else {
            b.addPath(
                pathData     = nodes,
                pathFillType = if (p.evenOdd) PathFillType.EvenOdd else PathFillType.NonZero,
                fill         = SolidColor(Color.Black),
                fillAlpha    = p.alpha
            )
        }
    }
    return b.build()
}
